package com.assetflow.api;
import org.springframework.http.ResponseEntity;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1")public class AssetController{private final JdbcTemplate db;public AssetController(JdbcTemplate db){this.db=db;}@GetMapping("/health")public Map<String,String> health(){return Map.of("status","ok");}@GetMapping("/dashboard")public Map<String,Object> dashboard(){int total=count("SELECT count(*) FROM asset"),online=count("SELECT count(*) FROM asset WHERE last_seen_at>now()-interval '15 minutes'"),stale=count("SELECT count(*) FROM asset WHERE last_seen_at<now()-interval '7 days'"),bitlocker=count("SELECT count(*) FROM asset WHERE bitlocker_enabled=false"),antivirus=count("SELECT count(*) FROM asset WHERE antivirus_status IS DISTINCT FROM 'Healthy'");return Map.of("total",total,"online",online,"offline",total-online,"stale",stale,"security",Map.of("bitlocker",bitlocker,"antivirus",antivirus));}@GetMapping("/assets")public List<Map<String,Object>>assets(@RequestParam(defaultValue="")String q){return db.queryForList("SELECT id,hostname,serial_no,manufacturer,model,username,department,os_name,os_version,ip_address,last_seen_at,(last_seen_at>now()-interval '15 minutes')online FROM asset WHERE hostname ILIKE ? OR coalesce(username,'') ILIKE ? ORDER BY last_seen_at DESC LIMIT 500","%"+q+"%","%"+q+"%");}@GetMapping("/assets/{id}")public ResponseEntity<?>asset(@PathVariable UUID id){var rows=db.queryForList("SELECT * FROM asset WHERE id=?",id);if(rows.isEmpty())return ResponseEntity.notFound().build();var out=new LinkedHashMap<>(rows.getFirst());out.put("disks",db.queryForList("SELECT name,filesystem,total_bytes,free_bytes FROM asset_disk WHERE asset_id=?",id));out.put("software",db.queryForList("SELECT name,version,publisher FROM asset_software WHERE asset_id=? ORDER BY name",id));return ResponseEntity.ok(out);}private int count(String sql){Integer n=db.queryForObject(sql,Integer.class);return n==null?0:n;}}
